import{useEffect,useMemo,useState}from"react";import type{RouteConfig}from"@mercurjs/dashboard-sdk";import{Actions,Button,Card,Empty,Field,FormGrid,Message,Page,PageHeader,Status}from"../../spike/ui";import{Input}from"../../components/ui/input";import{Select}from"../../components/ui/select";import{Table,TableBody,TableCell,TableHead,TableHeader,TableRow}from"../../components/ui/table";declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"الخصومات",rank:60};type Product={id:string;title:string;variants?:any[]};type Offer={id:string;prices?:any[];product_variant?:any};const base=()=>String(__BACKEND_URL__||"http://localhost:9000").replace(/\/$/,"");async function api(p:string,i?:RequestInit){const r=await fetch(base()+p,{credentials:"include",...i,headers:{...(i?.body?{"content-type":"application/json"}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d}const tone=(s:string)=>s==='approved'?'success':s==='rejected'?'danger':'warning' as any
export default function Discounts(){const[products,setProducts]=useState<Product[]>([]),[offers,setOffers]=useState<Offer[]>([]),[rows,setRows]=useState<any[]>([]),[productId,setProductId]=useState(""),[discount,setDiscount]=useState(""),[msg,setMsg]=useState("");const load=async()=>{const[p,o,d]=await Promise.all([api('/vendor/products?limit=200&fields=id,title,*variants'),api('/vendor/offers?limit=300&fields=id,*prices,*product_variant.product'),api('/vendor/spike/discounts')]);setProducts(p.products||[]);setOffers(o.offers||[]);setRows((d.discounts||[]).filter((x:any)=>x.request_type!=='coupon'))};useEffect(()=>{load().catch(e=>setMsg(e.message))},[]);const product=products.find(x=>x.id===productId);const offer=useMemo(()=>offers.find((o:any)=>o.product_variant?.product?.id===productId)||offers.find((o:any)=>product?.variants?.some(v=>v.id===o.product_variant?.id)),[offers,productId,product]);const price=Number(offer?.prices?.find((p:any)=>String(p.currency_code).toLowerCase()==='usd')?.amount||offer?.prices?.[0]?.amount||0),amount=Math.max(0,Number(discount)||0),after=Math.max(0,price-amount),pct=price>0?Math.round(amount/price*100):0;const send=async()=>{if(!product||!offer||!price)return setMsg('اختر منتجًا له سعر فعال');if(amount<=0||amount>=price)return setMsg('قيمة الخصم يجب أن تكون أكبر من صفر وأقل من السعر');await api('/vendor/spike/discounts',{method:'POST',body:JSON.stringify({offer_id:offer.id,product_id:product.id,product_title:product.title,original_price:price,discounted_price:after,currency_code:'USD'})});setDiscount('');setProductId('');setMsg('تم إرسال الخصم للأدمن للموافقة');load()};const del=async(id:string)=>{if(!confirm('حذف الخصم؟ إذا كان فعالاً سيتم إلغاؤه.'))return;try{await api(`/vendor/spike/discounts?id=${encodeURIComponent(id)}`,{method:'DELETE'});setMsg('تم حذف الخصم');load()}catch(e:any){setMsg(e.message)}};return <Page><PageHeader title="الخصومات" description="السعر الأساسي ثابت من المنتج بالدولار. أدخل قيمة الخصم فقط."/>{msg&&<Message>{msg}</Message>}<Card><FormGrid><Field label="المنتج"><Select value={productId} onValueChange={v=>{setProductId(v);setDiscount('')}} placeholder="اختر المنتج" options={products.map(p=>({value:p.id,label:p.title}))}/></Field><Field label="السعر الأصلي"><Input readOnly value={price?`${price} USD`:''}/></Field><Field label="قيمة الخصم"><Input type="number" min="0" value={discount} onChange={e=>setDiscount(e.target.value)} placeholder="مثال: 20"/></Field><Field label="السعر بعد الخصم"><Input readOnly value={price?`${after} USD`:''}/></Field></FormGrid><Actions><Button onClick={send}>إرسال للموافقة</Button>{pct>0&&<Status tone="info">≈ {pct}%</Status>}</Actions></Card><Card><h2>الخصومات السابقة</h2>{rows.length?<Table><TableHeader><TableRow><TableHead>المنتج</TableHead><TableHead>الخصم</TableHead><TableHead>الحالة</TableHead><TableHead>الإجراء</TableHead></TableRow></TableHeader><TableBody>{rows.map(r=><TableRow key={r.id}><TableCell>{r.product_title}</TableCell><TableCell>{r.percentage}%</TableCell><TableCell><Status tone={tone(r.status)}>{r.status==='pending'?'بانتظار الموافقة':r.status==='approved'?'مقبول':'مرفوض'}</Status></TableCell><TableCell><Button tone="danger" onClick={()=>del(r.id)}>حذف</Button></TableCell></TableRow>)}</TableBody></Table>:<Empty>لا توجد خصومات بعد</Empty>}</Card></Page>}
